    st=s.state(); arm=np.array(st['robot']['joint_positions'],float); f=np.array([.04,.04]); down=np.array([0.,1.,0.,0.]); q0=np.array([-.0171056526,-.69415678,.71925587,-.02290739])
    def goto(pos,q=down,delta=.004,settle=14):
        nonlocal_dummy=None
        global arm
        pos=np.asarray(pos,float); r=s.ik(pos,q); print('IK',pos,r['success'],flush=True)
        if not r['success']: return False
        goal=np.asarray(r['joint_positions'],float); start=arm.copy(); n=max(1,int(np.ceil(np.max(np.abs(goal-start))/delta)))
        if n+settle>4000: raise RuntimeError('action limit')
        for j in range(1,n+1): arm=start+(goal-start)*j/n; s.step(np.r_[arm,f])
        for _ in range(settle): s.step(np.r_[goal,f])
        arm=goal.copy(); actual=np.asarray(s.state()['robot']['tcp_position'],float); err=float(np.linalg.norm(actual-pos)); print('TCP',actual,'ERR',err,flush=True)
        return err<.045
    route=[(np.array([-.04,-.15,1.30]),q0), (np.array([-.04,-.15,1.30]),down),
           (np.array([-.04,0.,1.30]),down),(np.array([-.04,.10,1.30]),down),
           (np.array([-.04,.15,1.30]),down)]
    ok=True
    for pos,q in route:
        if not goto(pos,q): ok=False; break
    if ok:
        for z in [1.26,1.22,1.18,1.14,1.10,1.06,1.02,.98]:
            if not goto([-.04,.15,z],delta=.003,settle=12): ok=False; break
    if ok:
        for y in [.18,.20,.22,.24,.26,.28,.30,.32,.34]:
            if not goto([-.04,y,.98],delta=.003,settle=14): ok=False; break
    p=np.array(s.state()['entities']['juice_seen']['get_grasped_keypoints'][0],float)
    if ok:
        for pos in [[p[0],.35,.95],[p[0],p[1],.92],[p[0],p[1],p[2]]]:
            if not goto(pos,delta=.0025,settle=16): ok=False; break
    print('AT GRASP?',ok,'STATE',s.state()['robot'],flush=True)
    if ok:
        f[:]=0.
        for _ in range(25): s.step(np.r_[arm,f])
        print('CLOSED',s.state()['robot'],flush=True)
        # lift vertically, then extract through the opening
        for pos in [[p[0],p[1],.94],[p[0],p[1],1.00],[p[0],p[1],1.08],[p[0],p[1],1.15]]:
            if not goto(pos,delta=.003,settle=18): break
        for pos in [[p[0],.32,1.12],[p[0],.28,1.12],[p[0],.22,1.12],[p[0],.16,1.12]]:
            if not goto(pos,delta=.003,settle=18): break
    print('FINAL STATUS',s.status(),flush=True)
    print('FINAL STATE',s.state(),flush=True)
    actions=s.record_stop(); print('ACTIONS',actions.shape,flush=True)
    if s.status()['success']:
        s.save_trajectory(actions,'/app/output/trajectory.npz'); print('SAVED SUCCESS',flush=True)
